// Section 1 The basic economic problem (Cambridge 0455, exams 2027-2029): 1.1 to 1.4, and the English baseline.
// Writing rules: plain versions use short sentences and everyday words; key terms are marked [[term]] or [[term|shown words]]
// and open a pill with a simple definition, an easy example and (A1, if the class allows it) Vietnamese.

export const GLOSSARY = {
  'basic economic problem': { def: 'Resources are limited but wants are unlimited, so people must choose.', ex: 'You have 100,000 đồng but you want food, a book and a film ticket.', vi: 'vấn đề kinh tế cơ bản' },
  'scarcity': { def: 'There is not enough of something for everyone who wants it.', ex: 'There is not enough land in the city for everyone who wants a house.', vi: 'sự khan hiếm' },
  'scarce': { def: 'Limited: there is not enough for everyone who wants it.', ex: 'Clean water is scarce in a drought.', vi: 'khan hiếm' },
  'resources': { def: 'The things we use to make goods and services: natural resources, workers, machines and business skills.', ex: 'Rice fields, farmers and tractors are resources.', vi: 'nguồn lực' },
  'finite': { def: 'Limited. There is only a certain amount.', ex: 'There is only a certain amount of oil in the ground.', vi: 'hữu hạn' },
  'infinite': { def: 'With no end. People always want more.', ex: 'After a new phone, people want a laptop, then a holiday…', vi: 'vô hạn' },
  'wants': { def: 'Things people would like to have.', ex: 'A new phone, a holiday, a bigger house.', vi: 'mong muốn' },
  'needs': { def: 'Things people must have to live.', ex: 'Food, water, clothes and a home.', vi: 'nhu cầu thiết yếu' },
  'goods': { def: 'Things you can touch that people buy.', ex: 'Rice, phones, shoes.', vi: 'hàng hóa' },
  'services': { def: 'Things people do for you, which you cannot touch.', ex: 'A haircut, a bus ride, a lesson.', vi: 'dịch vụ' },
  'consumer': { def: 'A person who buys and uses goods and services.', ex: 'You are a consumer when you buy bubble tea.', vi: 'người tiêu dùng' },
  'producer': { def: 'A person or firm that makes goods or provides services.', ex: 'A rice farmer or a phone factory.', vi: 'nhà sản xuất' },
  'firm': { def: 'A business that makes goods or provides services.', ex: 'Vinamilk is a firm.', vi: 'doanh nghiệp' },
  'worker': { def: 'A person who works for a wage.', ex: 'A nurse or a factory worker.', vi: 'người lao động' },
  'government': { def: 'The group that runs a country and spends tax money.', ex: 'The government builds roads and schools.', vi: 'chính phủ' },
  'choice': { def: 'Picking one thing instead of another.', ex: 'Study tonight or go out with friends.', vi: 'sự lựa chọn' },
  'allocate': { def: 'To decide how to share out or use resources.', ex: 'A school decides how to use its budget.', vi: 'phân bổ' },
  'economic good': { def: 'A good that is scarce. Making it uses resources, so it has an opportunity cost.', ex: 'A bowl of phở, a bicycle, a laptop.', vi: 'hàng hóa kinh tế' },
  'free good': { def: 'A good that is not scarce. There is enough for everyone, so it has no opportunity cost.', ex: 'The air you breathe, sunlight.', vi: 'hàng hóa tự do' },
  'factors of production': { def: 'The four kinds of resources used to make goods and services: land, labour, capital and enterprise.', ex: 'A café needs a building (land), staff (labour), a coffee machine (capital) and an owner (enterprise).', vi: 'các yếu tố sản xuất' },
  'land': { def: 'All natural resources: fields, forests, rivers, the sea, fish, oil and minerals.', ex: 'The rice fields of the Mekong Delta.', vi: 'đất đai (tài nguyên thiên nhiên)' },
  'labour': { def: 'The work people do, with their bodies and their minds.', ex: 'A teacher, a builder, a programmer.', vi: 'lao động' },
  'capital': { def: 'Man-made things used to make other goods and services.', ex: 'Machines, tools, factories, computers, delivery vans.', vi: 'vốn (tư liệu sản xuất)' },
  'enterprise': { def: 'The skill of starting and running a business, and taking the risk.', ex: 'A person who opens a new bánh mì shop.', vi: 'năng lực kinh doanh (doanh nhân)' },
  'entrepreneur': { def: 'A person who starts a business, organises the other factors and takes the risk.', ex: 'Someone who borrows money to open a café.', vi: 'doanh nhân' },
  'reward': { def: 'The payment a factor of production earns.', ex: 'Workers earn wages; landowners earn rent.', vi: 'thu nhập của yếu tố sản xuất' },
  'rent': { def: 'The reward for land.', ex: 'A farmer pays rent to use a field.', vi: 'tiền thuê đất' },
  'wages': { def: 'The reward for labour: money paid for work.', ex: 'A worker earns 8 million đồng a month.', vi: 'tiền lương' },
  'interest': { def: 'The reward for capital: payment for lending money that buys capital.', ex: 'A bank pays you interest on your savings.', vi: 'tiền lãi' },
  'profit': { def: 'The reward for enterprise: money left after paying all costs.', ex: 'A shop sells 50 million and spends 40 million: profit is 10 million.', vi: 'lợi nhuận' },
  'quantity': { def: 'How much or how many there is.', ex: 'The number of workers in a country.', vi: 'số lượng' },
  'quality': { def: 'How good something is.', ex: 'Well-trained workers are higher quality labour.', vi: 'chất lượng' },
  'investment': { def: 'Spending on new capital, such as machines and factories.', ex: 'A firm buys 10 new sewing machines.', vi: 'đầu tư' },
  'technology': { def: 'New and better ways and tools for making things.', ex: 'Robots in a car factory.', vi: 'công nghệ' },
  'training': { def: 'Teaching workers new skills.', ex: 'A course that teaches workers to use a new machine.', vi: 'đào tạo' },
  'migration': { def: 'People moving to live in another place or country.', ex: 'Workers moving from Việt Nam to Japan.', vi: 'di cư' },
  'opportunity cost': { def: 'The next best thing you give up when you make a choice.', ex: 'You buy a film ticket instead of a book. The book is your opportunity cost.', vi: 'chi phí cơ hội' },
  'next best alternative': { def: 'The choice you would have made if you could not have your first choice.', ex: 'If you could not go to the cinema, you would buy a book.', vi: 'phương án tốt nhất tiếp theo' },
  'production possibility curve': { def: 'A curve showing all the combinations of two goods an economy can make when it uses all its resources fully.', ex: 'How much rice and how many phones Việt Nam could make.', vi: 'đường giới hạn khả năng sản xuất' },
  'PPC': { def: 'Short for production possibility curve: the combinations of two goods an economy can make when it uses all its resources fully.', ex: 'A curve with rice on one axis and phones on the other.', vi: 'đường giới hạn khả năng sản xuất' },
  'combination': { def: 'An amount of one good together with an amount of another.', ex: '8 million tonnes of rice and 6 million phones.', vi: 'sự kết hợp' },
  'efficient': { def: 'Using all resources fully, with nothing wasted.', ex: 'Every worker and machine is busy.', vi: 'hiệu quả' },
  'unemployed resources': { def: 'Resources that are not being used, such as workers without jobs or machines that stand still.', ex: 'A factory that is closed.', vi: 'nguồn lực không được sử dụng' },
  'unattainable': { def: 'Not possible to reach now, with the resources and technology we have today.', ex: 'Making more of both goods than the PPC shows.', vi: 'không thể đạt được' },
  'economic growth': { def: 'An increase in the amount an economy can produce.', ex: 'New technology lets Việt Nam make more of everything.', vi: 'tăng trưởng kinh tế' },
  'shift': { def: 'When the whole curve moves to a new place.', ex: 'The PPC moves outwards after new technology.', vi: 'dịch chuyển' },
  'trade-off': { def: 'Getting more of one thing means having less of another.', ex: 'More time on games means less time to study.', vi: 'sự đánh đổi' },
  'mobility': { def: 'How easily a factor of production can move to a different place or a different use.', ex: 'A worker moves from An Giang to Ho Chi Minh City.', vi: 'tính di động' },
  'geographical mobility': { def: 'How easily a factor can move to a different PLACE.', ex: 'A farmer moves from the countryside to the city to work.', vi: 'di chuyển về địa lý (nơi chốn)' },
  'occupational mobility': { def: 'How easily a factor can move to a different JOB or use.', ex: 'A rice farmer learns new skills and becomes a factory worker.', vi: 'di chuyển về nghề nghiệp' },
  'axis': { def: 'One of the two lines along the side and bottom of a graph.', ex: 'Rice is on the horizontal axis.', vi: 'trục' }
};

export const TRAPS = {
  'scarcity-def': { label: 'What scarcity means', tip: 'Scarcity is not "rare" or "expensive". It means wants are greater than the resources to satisfy them, so we must choose.' },
  'needs-wants': { label: 'Needs or wants?', tip: 'The basic economic problem is about unlimited WANTS (and needs) and limited RESOURCES. Resources are the limited side.' },
  'free-good': { label: 'Free good or free to the buyer?', tip: 'A free good is not scarce and has no opportunity cost (like air). Things the government gives free (like free school) still use scarce resources: they are economic goods.' },
  'three-questions': { label: 'What, how, for whom', tip: 'WHAT to produce = which goods. HOW to produce = which resources and methods. FOR WHOM = who gets the goods.' },
  'factor-type': { label: 'Which factor?', tip: 'Land = natural. Labour = human work. Capital = man-made tools and machines. Enterprise = taking the risk and organising.' },
  'money-capital': { label: 'Money is not capital', tip: 'In economics, capital means man-made goods used in production (machines, tools, buildings), not money in the bank.' },
  'reward-match': { label: 'Matching rewards', tip: 'Land → rent. Labour → wages. Capital → interest. Enterprise → profit.' },
  'quantity-quality': { label: 'Quantity or quality?', tip: 'Quantity = how many or how much (more workers, more land). Quality = how good (better skills, more fertile soil).' },
  'oc-def': { label: 'What opportunity cost means', tip: 'Opportunity cost is the NEXT BEST alternative given up. Not the money price, and not everything you gave up.' },
  'oc-all': { label: 'Only the next best', tip: 'Count only the single next best choice you gave up, not all the other choices added together.' },
  'ppc-point': { label: 'Inside, on or outside?', tip: 'On the curve: all resources used fully. Inside: some resources unemployed. Outside: unattainable with today\'s resources.' },
  'ppc-oc': { label: 'Reading opportunity cost on a PPC', tip: 'Moving along the curve, the opportunity cost of more of one good is how much of the OTHER good you give up.' },
  'ppc-shift': { label: 'Movement or shift?', tip: 'Using resources differently = a movement ALONG the curve. More or better resources, or new technology = a SHIFT of the whole curve.' },
  'mobility': { label: 'Geographical or occupational?', tip: 'Geographical mobility = moving to a different PLACE. Occupational mobility = moving to a different JOB or use. Land cannot move place at all.' },
  'ppc-dir': { label: 'Which way does it shift?', tip: 'More or better resources → outwards (economic growth). Fewer resources (war, disaster, emigration) → inwards.' }
};

