// ---------- PPC explorer (1.4): a PPC for rice (horizontal, million tonnes) and phones (vertical, millions).
// The curve passes through A(0,10), B(6,8), C(8,6), D(10,0): a quarter circle of radius 10, so the numbers are exact.
export const PPC_POINTS = { A: [0, 10], B: [6, 8], C: [8, 6], D: [10, 0], E: [4, 5], F: [9, 8] };
const choice = (q, answer, options, why, trap) => ({ q, type: 'choice', answer, options: options.map(([t, v, tr]) => ({ t, v, trap: tr || trap })), why });
const num = (q, answer, unit, why, trap) => ({ q, type: 'number', answer, unit, why, trap });
